function resolveTargetEnvironment() {
  const envValue =
    process.env.TRANSLATIONS_TARGET_ENV ||
    process.env.DEPLOY_ENV ||
    process.env.ENVIRONMENT ||
    '';
  return String(envValue).trim().toLowerCase();
}

function shouldUseDraftValues(targetEnvironment) {
  return !targetEnvironment || targetEnvironment === 'sit';
}

module.exports = {
  resolveTargetEnvironment,
  shouldUseDraftValues,
};
